package org.apache.commons.math.stat;

import java.io.*;
import java.io.Serializable;
import java.math.*;
import java.text.NumberFormat;
import java.util.*;
import java.util.Comparator;
import java.util.Iterator;
import java.util.TreeMap;
import org.apache.commons.math.MathRuntimeException;
import org.junit.*;
import org.junit.Before;
import org.junit.Test;
import static org.junit.Assert.*;
import static org.junit.Assert.assertEquals;

public class Frequency_getPct_TriageGen3Test {

    private Frequency frequency;

    @Before
    public void setUp() {
        frequency = new Frequency();
    }

    @Test
    public void testGetPct_WithExistingInteger() {
        frequency.addValue(10);
        frequency.addValue(20);
        frequency.addValue(10);
        // Total count = 3. Count of 10 = 2. Pct = 2/3
        double expected = 2.0 / 3.0;
        assertEquals(expected, frequency.getPct(10), 1e-15);
    }

    @Test
    public void testGetPct_WithExistingString() {
        frequency.addValue("A");
        frequency.addValue("B");
        frequency.addValue("A");
        // Total count = 3. Count of "A" = 2. Pct = 2/3
        double expected = 2.0 / 3.0;
        assertEquals(expected, frequency.getPct("A"), 1e-15);
    }

    @Test
    public void testGetPct_WithNonExistentValue() {
        frequency.addValue(1);
        frequency.addValue(2);
        // Total count = 2. Count of 3 = 0. Pct = 0.0
        assertEquals(0.0, frequency.getPct(3), 1e-15);
    }

    @Test
    public void testGetPct_EmptyFrequency() {
        // Total count = 0. Pct should be 0.0 (standard behavior for Frequency class when total is 0)
        assertEquals(0.0, frequency.getPct(10), 1e-15);
    }

    @Test(expected = ClassCastException.class)
    public void testGetPct_WithNonComparableObject() {
        // Create an object that does not implement Comparable
        Object nonComparable = new Object();
        frequency.addValue(10);
        // This should trigger ClassCastException because getPct casts v to Comparable<?>
        frequency.getPct(nonComparable);
    }

    @Test
    public void testGetPct_WithDouble() {
        // Doubles are Comparable
        frequency.addValue(1.5);
        frequency.addValue(2.5);
        frequency.addValue(1.5);
        double expected = 2.0 / 3.0;
        assertEquals(expected, frequency.getPct(1.5), 1e-15);
    }

    @Test
    public void testGetPct_WithCharacter() {
        frequency.addValue('a');
        frequency.addValue('b');
        assertEquals(0.5, frequency.getPct('a'), 1e-15);
    }
}
